const syncAgentProjection = `-- name: SyncAgentProjection :one
UPDATE agent AS p
SET name = s.name,
    description = s.description,
    avatar_url = s.avatar_url,
    runtime_mode = s.runtime_mode,
    runtime_id = (
        SELECT pr.id
        FROM agent_runtime sr
        JOIN agent_runtime pr
          ON pr.workspace_id = p.workspace_id
         AND pr.daemon_id = sr.daemon_id
         AND pr.provider = sr.provider
         AND pr.owner_id IS NOT DISTINCT FROM sr.owner_id
        LEFT JOIN runtime_profile sp ON sp.id = sr.profile_id
        LEFT JOIN runtime_profile pp ON pp.id = pr.profile_id
        WHERE sr.id = s.runtime_id
          AND (pr.profile_id IS NULL) = (sr.profile_id IS NULL)
          AND (sr.profile_id IS NULL OR pp.display_name = sp.display_name)
        ORDER BY pr.last_seen_at DESC NULLS LAST
        LIMIT 1
    ),
    visibility = s.visibility,
    permission_mode = s.permission_mode,
    max_concurrent_tasks = s.max_concurrent_tasks,
    instructions = s.instructions,
    custom_args = s.custom_args,
    conversation_starters = s.conversation_starters,
    model = s.model,
    thinking_level = s.thinking_level,
    service_tier = s.service_tier,
    intake_can = s.intake_can,
    intake_cannot = s.intake_cannot,
    org_unit_id = s.org_unit_id,
    owner_id = s.owner_id,
    is_primary = s.is_primary
        AND s.archived_at IS NULL
        AND p.archived_at IS NULL
        AND NOT EXISTS (
            SELECT 1 FROM agent o
            WHERE o.workspace_id = p.workspace_id
              AND o.owner_id = s.owner_id
              AND o.kind = 'user'
              AND o.archived_at IS NULL
              AND o.is_primary
              AND o.id <> p.id
        ),
    updated_at = now()
FROM agent s
WHERE p.id = $1
  AND s.id = p.source_agent_id
RETURNING p.id, p.workspace_id, p.name, p.avatar_url, p.runtime_mode, p.runtime_config, p.visibility, p.status, p.max_concurrent_tasks, p.owner_id, p.created_at, p.updated_at, p.description, p.runtime_id, p.instructions, p.archived_at, p.archived_by, p.custom_env, p.custom_args, p.mcp_config, p.model, p.thinking_level, p.composio_toolkit_allowlist, p.permission_mode, p.kind, p.system_key, p.disabled_runtime_skills, p.service_tier, p.conversation_starters, p.intake_can, p.intake_cannot, p.org_unit_id, p.is_primary, p.source_agent_id
`

// Re-reads the source into one projection. is_primary follows the source but
// never displaces another primary the owner already has in the project.
func (q *Queries) SyncAgentProjection(ctx context.Context, id pgtype.UUID) (Agent, error) {
	row := q.db.QueryRow(ctx, syncAgentProjection, id)
	var i Agent
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Name,
		&i.AvatarUrl,
		&i.RuntimeMode,
		&i.RuntimeConfig,
		&i.Visibility,
		&i.Status,
		&i.MaxConcurrentTasks,
		&i.OwnerID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Description,
		&i.RuntimeID,
		&i.Instructions,
		&i.ArchivedAt,
		&i.ArchivedBy,
		&i.CustomEnv,
		&i.CustomArgs,
		&i.McpConfig,
		&i.Model,
		&i.ThinkingLevel,
		&i.ComposioToolkitAllowlist,
		&i.PermissionMode,
		&i.Kind,
		&i.SystemKey,
		&i.DisabledRuntimeSkills,
		&i.ServiceTier,
		&i.ConversationStarters,
		&i.IntakeCan,
		&i.IntakeCannot,
		&i.OrgUnitID,
		&i.IsPrimary,
		&i.SourceAgentID,
	)
	return i, err
}

const syncAgentProjectionInvocationTargets = `-- name: SyncAgentProjectionInvocationTargets :exec
WITH desired AS MATERIALIZED (
    SELECT
        p.id AS agent_id,
        t.target_type,
        CASE
            WHEN t.target_type = 'workspace' THEN p.workspace_id
            ELSE t.target_id
        END AS target_id,
        t.created_by
    FROM agent p
    JOIN agent_invocation_target t ON t.agent_id = p.source_agent_id
    WHERE p.id = $1
),
upserted AS (
    INSERT INTO agent_invocation_target (
        agent_id, target_type, target_id, created_by
    )
    SELECT agent_id, target_type, target_id, created_by
    FROM desired
    ON CONFLICT (agent_id, target_type, target_id) DO UPDATE SET
        created_by = EXCLUDED.created_by,
        created_at = now()
    RETURNING 1
)
DELETE FROM agent_invocation_target current
WHERE current.agent_id = $1
  AND (SELECT count(*) FROM upserted) >= 0
  AND NOT EXISTS (
      SELECT 1
      FROM desired
      WHERE desired.target_type = current.target_type
        AND desired.target_id IS NOT DISTINCT FROM current.target_id
  )
`

// Mirrors the source allow-list into one project projection. Workspace-wide
// access is remapped to the projection's workspace; member and team ids are
// organization-global and carry across unchanged.
func (q *Queries) SyncAgentProjectionInvocationTargets(ctx context.Context, projectionID pgtype.UUID) error {
	_, err := q.db.Exec(ctx, syncAgentProjectionInvocationTargets, projectionID)
	return err
}
